25	/**
26	 * Emits an audit trail entry when an {@link Owner} is created. On a successful
27	 * insert the {@code AUDIT} logger records the new owner's id, customer code and
28	 * registration date.
29	 */
30	public class OwnerAuditListener {
31	
32	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
33	
34	    private static final Logger NOTIFY = LoggerFactory.getLogger("NOTIFY");
35	
36	    private static final java.util.concurrent.atomic.AtomicLong OWNER_SEQ = new java.util.concurrent.atomic.AtomicLong();
37	
38	    @PostPersist
39	    void onCreate(Owner owner) {
40	        String memberId = org.springframework.samples.petclinic.util.MemberIds.of(owner);
41	        NOTIFY.info("welcome owner id={} memberId={}", owner.getId(), memberId);
42	        AUDIT.info("owner created id={} memberId={} registrationDate={} membershipLevel={}",
43	            owner.getId(), memberId, owner.getRegistrationDate(),
44	            Membership.level(Membership.points(owner, false, false)));
45	        AUDIT.info("{\"seq\":{},\"ownerId\":{},\"memberId\":\"{}\",\"membershipLevel\":{},\"event\":\"OWNER_CREATED\"}",
46	            OWNER_SEQ.incrementAndGet(), owner.getId(), memberId,
47	            Membership.level(Membership.points(owner, false, false)));
48	    }
