1	package org.springframework.samples.petclinic.util;
2	
3	/**
4	 * Computes the Luhn check digit over the digits contained in a string.
5	 */
6	public final class Luhn {
7	
8	    private Luhn() {
9	    }
10	
11	    /** The Luhn check digit (0-9) over the digits contained in {@code s}. */
12	    public static int checkDigit(String s) {
13	        int sum = 0;
14	        boolean dbl = true;
15	        for (int i = s.length() - 1; i >= 0; i--) {
16	            char c = s.charAt(i);
17	            if (c < '0' || c > '9') {
18	                continue;
19	            }
20	            int d = c - '0';
21	            if (dbl && (d *= 2) > 9) {
22	                d -= 9;
23	            }
24	            sum += d;
25	            dbl = !dbl;
26	        }
27	        return (10 - (sum % 10)) % 10;
28	    }
29	}
