1	package org.springframework.samples.petclinic.util;
2	
3	/**
4	 * American Soundex phonetic coding of a surname: the first letter followed by three
5	 * digits, zero-padded and truncated to length four (e.g. {@code Robert -> R163}).
6	 * A null or letter-free value codes to the empty string.
7	 */
8	public final class Soundex {
9	
10	    /** Per-letter code for A..Z; '0' marks a letter that is not coded. */
11	    private static final String MAP = "01230120022455012623010202";
12	
13	    private Soundex() {
14	    }
15	
16	    /** The four-character Soundex code of {@code value}, or "" when it has no letters. */
17	    public static String of(String value) {
18	        if (value == null) {
19	            return "";
20	        }
21	        StringBuilder letters = new StringBuilder();
22	        for (int i = 0; i < value.length(); i++) {
23	            char c = Character.toUpperCase(value.charAt(i));
24	            if (c >= 'A' && c <= 'Z') {
25	                letters.append(c);
26	            }
27	        }
28	        if (letters.length() == 0) {
29	            return "";
30	        }
31	        StringBuilder out = new StringBuilder().append(letters.charAt(0));
32	        char prev = MAP.charAt(letters.charAt(0) - 'A');
33	        for (int i = 1; i < letters.length() && out.length() < 4; i++) {
34	            char c = letters.charAt(i);
35	            char code = MAP.charAt(c - 'A');
36	            if (code != '0' && code != prev) {
37	                out.append(code);
38	            }
39	            if (c != 'H' && c != 'W') {
40	                prev = code;
41	            }
42	        }
43	        while (out.length() < 4) {
44	            out.append('0');
45	        }
46	        return out.toString();
47	    }
48	}
